// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @title PartyToken
/// @notice Minimal fixed-supply ERC20 launched by PartyFactory via CREATE2.
/// @dev No owner, no mint, no transfer hooks. The full supply is minted once to
///      `recipient` (the factory) in the constructor. The caller-bound CREATE2
///      salt is mined off-chain so this token sorts below the paired asset (token0).
contract PartyToken is ERC20 {
    /// @notice IPFS (or https) URI of the token's metadata JSON.
    string public metadataUri;

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 supply_,
        address recipient_,
        string memory metadataUri_
    ) ERC20(name_, symbol_) {
        metadataUri = metadataUri_;
        _mint(recipient_, supply_);
    }

    /// @notice Alias for `metadataUri`, mirroring the ERC721 tokenURI convention.
    function tokenURI() external view returns (string memory) {
        return metadataUri;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

/// @dev Minimal Chainlink Data Feed surface used by PartyFactory: USD price
///      feeds per paired asset, and the L2 sequencer-uptime feed (answer 0 = up,
///      1 = down; startedAt = when the current status began).
interface IChainlinkAggregatorV3 {
    function decimals() external view returns (uint8);

    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

/// @notice Minimal SushiSwap/Uniswap V3 NonfungiblePositionManager interface.
/// @dev The NPM handles its own mint callback (pulling tokens via transferFrom
///      from the approved caller), so pools.fun only needs to approve + mint +
///      collect. No mint-callback implementation is required on our side.
interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);

    struct CollectParams {
        uint256 tokenId;
        address recipient;
        uint128 amount0Max;
        uint128 amount1Max;
    }

    function collect(CollectParams calldata params) external payable returns (uint256 amount0, uint256 amount1);

    function positions(uint256 tokenId)
        external
        view
        returns (
            uint96 nonce,
            address operator,
            address token0,
            address token1,
            uint24 fee,
            int24 tickLower,
            int24 tickUpper,
            uint128 liquidity,
            uint256 feeGrowthInside0LastX128,
            uint256 feeGrowthInside1LastX128,
            uint128 tokensOwed0,
            uint128 tokensOwed1
        );

    function factory() external view returns (address);

    function WETH9() external view returns (address);

    function ownerOf(uint256 tokenId) external view returns (address);

    function safeTransferFrom(address from, address to, uint256 tokenId) external;
}

